@push('styles')
<style>
.legal-settings{max-width:1250px;margin:auto;padding:20px 12px 40px;color:#243547}.legal-settings .legal-card{background:white;border:1px solid #dce4e9;border-radius:14px;padding:24px;margin:18px 0;box-shadow:0 3px 12px #1231}.legal-settings .legal-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.legal-settings .legal-grid .legal-card{margin:0}.legal-settings h1{font-size:26px;margin:10px 0}.legal-settings h2{font-size:20px;margin-bottom:14px}.legal-settings h3{font-size:17px}.legal-settings p,.legal-settings small{line-height:1.6}.legal-settings .muted{color:#637587}.legal-settings label{display:block;font-weight:600;margin:14px 0 6px}.legal-settings input:not([type=checkbox]),.legal-settings select,.legal-settings textarea{width:100%;padding:10px 12px;border:1px solid #b8c6ce;border-radius:7px;background:#fff;color:#243547}.legal-settings textarea{line-height:1.7;resize:vertical}.legal-settings .inline-check{display:flex;align-items:center;gap:10px;font-weight:400}.legal-settings .inline-check input{width:18px;height:18px}.legal-settings .legal-actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:16px 0}.legal-settings .signature-preview{max-width:240px;height:100px;object-fit:contain;border:1px dashed #cbd5e1;background:#fafafa;padding:8px}.legal-settings .legal-table{width:100%;border-collapse:collapse}.legal-settings .legal-table th,.legal-settings .legal-table td{padding:12px;border-bottom:1px solid #dce4e9;text-align:left;vertical-align:top}.legal-settings .table-scroll{overflow-x:auto}.legal-settings .badge-draft{background:#fff3cd;color:#785a00;padding:5px 9px;border-radius:15px}.legal-settings .badge-valid{background:#dcfce7;color:#166534;padding:5px 9px;border-radius:15px}.legal-settings .form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 20px}.legal-settings .schedule-row{background:#f4f7f9;padding:16px;border-radius:8px;margin:12px 0}.legal-settings .variables{display:flex;gap:8px;flex-wrap:wrap}.legal-settings code{overflow-wrap:anywhere}.legal-settings .warning{background:#fff7dc;border-left:4px solid #b48a00;padding:12px 16px}.legal-settings .legal-body{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7}
.legal-rich{white-space:normal!important}.legal-rich table{width:100%;border-collapse:collapse}.legal-rich td,.legal-rich th{border:1px solid #bcc8ce;padding:8px}.legal-rich ul{list-style:disc;padding-left:25px}.legal-rich ol{list-style:decimal;padding-left:25px}.legal-rich h1,.legal-rich h2,.legal-rich h3{margin:16px 0 8px}.legal-rich p{margin:0 0 10px}.legal-settings .note-editor .note-editable{background:#fff;min-height:400px}.legal-settings .note-editor .note-editable ul{list-style:disc;padding-left:25px}.legal-settings .note-editor .note-editable ol{list-style:decimal;padding-left:25px}.legal-settings .note-btn{width:auto}.legal-settings .note-editor label{margin:0}
@media(max-width:760px){.legal-settings .legal-grid,.legal-settings .form-grid{grid-template-columns:1fr}.legal-settings .legal-card{padding:16px}}
</style>
@endpush
